```javascript
function parseNewsText(text) {
  const titleRegex = /^(.+?)\;/;
  const dateRegex = /(\d{1,2}:\d{2}am|pm)/;

  const titleMatch = titleRegex.exec(text);
  const dateMatch = dateRegex.exec(text);

  if (titleMatch && dateMatch) {
    const title = titleMatch[1];
    const hourOrDate = dateMatch[1];

    return {
      title: title,
      hour_or_date: hourOrDate
    };
  } else {
    return null;
  }
}

const inputText = "Mib maglia rosa; pushes Moncler after results\n06:12am\nAN";
const result = parseNewsText(inputText);
console.log(result);
```
